FINGER_NOTE = 'Киберпалец. Нужна киберрука с модульными пальцами. Дайналар возвращается после перебоя поставок после 4-й корпоративной войны. '


def build(out):
    P = 'bc'
    out.pack(P, 'Чёрный хром', 'Black Chrome')
    e = find('bc_ru', 'Using Black Chrome', kind='section')
    lib = {'Lib': e['id']}
    for name, brand, cost, text, page in APPS:
        out.add(P, 'gear', name, cost=cost, Group='Приложения', Info=text + ' От ' + brand + '.', Page=page, **lib,
                Extra={'type': 'app', 'brand': brand})
    for name, cost, hl, install, cat, slots, req, found, text, page in CYBER:
        cats = [cat]
        if name in LIMB:
            cats = [ARM, LEG]
        for c in cats:
            out.add(P, 'cyber', name, cost=cost, HL=hl, Install=install or None, Category=c, Slots=slots,
                    Requires=('Кибернога' if c == LEG and req == 'Киберрука' else req) or None, Foundation=found, Info=text, Page=page, **lib)
    for name, cost, hl, text, page in FINGERS:
        out.add(P, 'cyber', name, cost=cost, HL=hl, Install='Молл', Category=ARM, Slots=0, Requires='Киберрука с модульными пальцами',
                Info=FINGER_NOTE + text, Page=page, Extra={'type': 'finger'}, **lib)
